import React, { useState } from 'react';
import { View, Text, StyleSheet, Dimensions, TouchableWithoutFeedback } from 'react-native';

const { width: screenWidth } = Dimensions.get('window');
const chartWidth = screenWidth - 64;

// Simple Line Chart Component
export const SimpleLineChart = ({ data, height = 180, color = '#007AFF', title, subtitle, labels, smooth = true }) => {
  const [selectedPoint, setSelectedPoint] = useState(null);
  
  // Handle both old format (array) and new format (object with data and labels)
  const chartData = Array.isArray(data) ? data : data?.data || [];
  const chartLabels = labels || data?.labels || [];
  
  if (!chartData || chartData.length === 0) {
    return (
      <View style={[styles.chartContainer, { height }]}>
        <Text style={styles.noDataText}>No data available</Text>
      </View>
    );
  }

  const maxValue = Math.max(...chartData);
  const minValue = Math.min(...chartData);
  const range = maxValue - minValue || 1;
  
  const chartHeight = height - 60; // More space for x-axis labels
  const actualChartWidth = chartWidth - 40; // Account for y-axis labels
  const pointWidth = Math.max(actualChartWidth / Math.max(1, chartData.length - 1), 20); // Min spacing

  const points = chartData.map((value, index) => ({
    x: Math.min(index * pointWidth, actualChartWidth - 6), // Ensure points stay within bounds
    y: Math.max(6, chartHeight - ((value - minValue) / range) * chartHeight), // Ensure points stay within bounds
    value,
    label: chartLabels[index] || `Point ${index + 1}`
  }));

  // Generate smooth curve path for SVG-like rendering
  const generateSmoothPath = (points) => {
    if (points.length < 2) return [];
    
    const smoothPoints = [];
    for (let i = 0; i < points.length - 1; i++) {
      const current = points[i];
      const next = points[i + 1];
      
      if (smooth && i < points.length - 2) {
        // Bezier curve control points
        const controlX1 = current.x + (next.x - current.x) * 0.3;
        const controlY1 = current.y;
        const controlX2 = next.x - (next.x - current.x) * 0.3;
        const controlY2 = next.y;
        
        smoothPoints.push({
          type: 'curve',
          x1: current.x,
          y1: current.y,
          x2: next.x,
          y2: next.y,
          controlX1,
          controlY1,
          controlX2,
          controlY2
        });
      } else {
        // Straight line
        smoothPoints.push({
          type: 'line',
          x1: current.x,
          y1: current.y,
          x2: next.x,
          y2: next.y
        });
      }
    }
    return smoothPoints;
  };

  const pathSegments = generateSmoothPath(points);

  return (
    <View style={styles.chartWrapper}>
      {title && <Text style={styles.chartTitle}>{title}</Text>}
      {subtitle && <Text style={styles.chartSubtitle}>{subtitle}</Text>}
      <View style={[styles.chartContainer, { height, width: chartWidth }]}>
        {/* Y-axis labels */}
        <View style={styles.yAxisLabels}>
          <Text style={styles.axisLabel}>{maxValue.toFixed(1)}</Text>
          <Text style={styles.axisLabel}>{((maxValue + minValue) / 2).toFixed(1)}</Text>
          <Text style={styles.axisLabel}>{minValue.toFixed(1)}</Text>
        </View>
        
        {/* Chart area */}
        <View style={[styles.chartArea, { width: chartWidth - 40 }]}>
          {/* Grid lines */}
          <View style={styles.gridContainer}>
            {[0, 1, 2, 3].map(i => (
              <View key={i} style={[styles.gridLine, { top: (i * chartHeight) / 3 }]} />
            ))}
          </View>
          
          {/* Data points and lines */}
          <View style={styles.dataContainer}>
            {points.map((point, index) => (
              <View key={index}>
                {/* Line to next point */}
                {index < points.length - 1 && (
                  <View
                    style={[
                      styles.line,
                      {
                        left: point.x,
                        top: point.y,
                        width: Math.sqrt(
                          Math.pow(points[index + 1].x - point.x, 2) +
                          Math.pow(points[index + 1].y - point.y, 2)
                        ),
                        transform: [
                          {
                            rotate: `${Math.atan2(
                              points[index + 1].y - point.y,
                              points[index + 1].x - point.x
                            )}rad`,
                          },
                        ],
                        backgroundColor: color,
                      },
                    ]}
                  />
                )}
                
                {/* Data point */}
                <View
                  style={[
                    styles.dataPoint,
                    {
                      left: point.x - 3,
                      top: point.y - 3,
                      backgroundColor: color,
                    },
                  ]}
                />
              </View>
            ))}
          </View>
        </View>
      </View>
    </View>
  );
};

// Simple Bar Chart Component
export const SimpleBarChart = ({ data, labels, height = 180, color = '#007AFF', title, subtitle }) => {
  if (!data || data.length === 0) {
    return (
      <View style={[styles.chartContainer, { height }]}>
        <Text style={styles.noDataText}>No data available</Text>
      </View>
    );
  }

  const maxValue = Math.max(...data) || 1;
  const chartHeight = height - 60;
  const barWidth = (chartWidth - 80) / data.length - 8;

  return (
    <View style={styles.chartWrapper}>
      {title && <Text style={styles.chartTitle}>{title}</Text>}
      {subtitle && <Text style={styles.chartSubtitle}>{subtitle}</Text>}
      <View style={[styles.chartContainer, { height, width: chartWidth }]}>
        {/* Y-axis labels */}
        <View style={styles.yAxisLabels}>
          <Text style={styles.axisLabel}>{maxValue}</Text>
          <Text style={styles.axisLabel}>{Math.round(maxValue / 2)}</Text>
          <Text style={styles.axisLabel}>0</Text>
        </View>
        
        {/* Chart area */}
        <View style={[styles.chartArea, { width: chartWidth - 40 }]}>
          {/* Bars */}
          <View style={styles.barsContainer}>
            {data.map((value, index) => {
              const barHeight = Math.max((value / maxValue) * chartHeight, 2); // Min height
              return (
                <View key={index} style={styles.barColumn}>
                  <View
                    style={[
                      styles.bar,
                      {
                        height: barHeight,
                        width: Math.min(barWidth, 40), // Max width to prevent overflow
                        backgroundColor: color,
                      },
                    ]}
                  />
                  <Text style={styles.barValue}>{value}</Text>
                  {labels && labels[index] && (
                    <Text style={styles.barLabel} numberOfLines={1}>{labels[index]}</Text>
                  )}
                </View>
              );
            })}
          </View>
        </View>
      </View>
    </View>
  );
};

// Simple Progress Bar Component
export const SimpleProgressBar = ({ current, total, height = 8, color = '#007AFF', backgroundColor = '#e5e5e5' }) => {
  const percentage = Math.min((current / total) * 100, 100);
  
  return (
    <View style={[styles.progressBar, { height, backgroundColor }]}>
      <View
        style={[
          styles.progressFill,
          {
            width: `${percentage}%`,
            height,
            backgroundColor: color,
          },
        ]}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  chartWrapper: {
    backgroundColor: '#fff',
    marginHorizontal: 16,
    marginBottom: 20,
    borderRadius: 12,
    padding: 16,
    elevation: 2,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
  },
  chartTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: '#333',
    marginBottom: 4,
  },
  chartSubtitle: {
    fontSize: 14,
    color: '#666',
    marginBottom: 12,
  },
  chartContainer: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    position: 'relative',
    borderBottomWidth: 1,
    borderLeftWidth: 1,
    borderColor: '#e5e5e5',
    overflow: 'hidden', // Prevent content from overflowing
  },
  yAxisLabels: {
    width: 40,
    height: '100%',
    justifyContent: 'space-between',
    alignItems: 'flex-end',
    paddingRight: 8,
    paddingBottom: 20,
  },
  axisLabel: {
    fontSize: 12,
    color: '#666',
  },
  chartArea: {
    position: 'relative',
    height: '100%',
    overflow: 'hidden', // Prevent content from overflowing
  },
  gridContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 20,
  },
  gridLine: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 1,
    backgroundColor: '#f0f0f0',
  },
  dataContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 20,
  },
  line: {
    position: 'absolute',
    height: 2,
    transformOrigin: 'left center',
  },
  dataPoint: {
    width: 6,
    height: 6,
    borderRadius: 3,
  },
  dataPointTouchable: {
    position: 'absolute',
    width: 20,
    height: 20,
    justifyContent: 'center',
    alignItems: 'center',
  },
  tooltip: {
    position: 'absolute',
    backgroundColor: 'rgba(0, 0, 0, 0.8)',
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 4,
    zIndex: 1000,
  },
